CREATE OR REPLACE FUNCTION public.protect_model_catalog() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $$ BEGIN IF TG_OP='DELETE' THEN IF EXISTS(SELECT 1 FROM public.model_subtiles WHERE model_id=OLD.id AND is_approved_for_coordinates) THEN RAISE EXCEPTION 'Approved model cannot be deleted'; END IF; RETURN OLD; END IF; IF OLD.is_published AND NOT NEW.is_published AND EXISTS(SELECT 1 FROM public.model_subtiles WHERE model_id=OLD.id AND is_approved_for_coordinates) THEN RAISE EXCEPTION 'Approved model cannot be unpublished'; END IF; -- Generated center columns are computed AFTER BEFORE triggers and must not be compared here.
IF ROW(NEW.bbox_north,NEW.bbox_south,NEW.bbox_east,NEW.bbox_west) IS DISTINCT FROM ROW(OLD.bbox_north,OLD.bbox_south,OLD.bbox_east,OLD.bbox_west) THEN RAISE EXCEPTION 'Geometry is immutable'; END IF; RETURN NEW; END; $$;